const input = $json ?? {};

const sourceId =
  'integration.apify_google_maps_scraper';

const platformSourceId =
  'general.google_maps';

const actorId =
  'nwua9Gu5YrADL7ZDj';

const actorName =
  'compass/crawler-google-places';

if (!input.run_id) {
  throw new Error('run_id is required.');
}

if (
  input.source_id &&
  input.source_id !== sourceId
) {
  throw new Error(
    `Google Maps received unexpected source_id: ` +
    `${input.source_id}`
  );
}

const segment = String(
  input.segment || 'farrier'
).trim().toLowerCase();

if (
  !['farrier', 'horse_owner'].includes(segment)
) {
  throw new Error(
    'segment must be farrier or horse_owner.'
  );
}

const requested = Number(
  input.maximum_results ??
  input.max_results
);

if (
  !Number.isInteger(requested) ||
  requested < 1 ||
  requested > 200
) {
  throw new Error(
    'maximum_results must be an integer between 1 and 200.'
  );
}

const maximumResults = requested;

const location = input.location || {};
const locationKey = String(
  input.location_key || ''
).trim();

const sourceScopeKey = String(
  input.source_scope_key || ''
).trim();

if (!locationKey) {
  throw new Error('location_key is required.');
}

if (!sourceScopeKey) {
  throw new Error('source_scope_key is required.');
}

const city = String(
  location.city || ''
).trim();

const region = String(
  location.region ||
  location.state ||
  ''
).trim();

const regionCode = String(
  location.region_code ||
  location.state_code ||
  ''
).trim().toUpperCase();

const country = String(
  location.country || ''
).trim();

const countryCode = String(
  location.country_code || ''
).trim().toUpperCase();

if (!city) {
  throw new Error('location.city is required.');
}

if (!country) {
  throw new Error('location.country is required.');
}

if (!/^[A-Z]{2}$/.test(countryCode)) {
  throw new Error(
    'location.country_code must be a two-letter ISO country code.'
  );
}

const locationQuery = String(
  location.location_display ||
  [city, region, country]
    .filter(Boolean)
    .join(', ')
).trim();

if (!locationQuery) {
  throw new Error(
    'A valid location query could not be built.'
  );
}

const previousPosition =
  input.previous_position ??
  input.cursor ??
  {};

if (
  previousPosition &&
  (
    typeof previousPosition !== 'object' ||
    Array.isArray(previousPosition)
  )
) {
  throw new Error(
    'Google Maps cursor must be an object.'
  );
}

if (
  previousPosition.source_id &&
  previousPosition.source_id !== sourceId
) {
  throw new Error(
    'Google Maps cursor belongs to another source.'
  );
}

if (
  previousPosition.segment &&
  previousPosition.segment !== segment
) {
  throw new Error(
    'Google Maps cursor belongs to another segment.'
  );
}

if (
  previousPosition.location_key &&
  previousPosition.location_key !== locationKey
) {
  throw new Error(
    'Google Maps cursor belongs to another location.'
  );
}

const queryCatalog =
  segment === 'farrier'
    ? [
        'farrier',
        'horseshoeing service'
      ]
    : [
        'horse farm',
        'horse boarding stable',
        'equestrian center',
        'horse breeder',
        'horse trainer'
      ];

const queryCount = Math.min(
  queryCatalog.length,
  maximumResults
);

const searchStrings =
  queryCatalog.slice(0, queryCount);

const maxPerSearch = Math.ceil(
  maximumResults / queryCount
);

const plannedMaximumItems =
  searchStrings.length * maxPerSearch;

const requestedDatasetPageLimit = Number(
  input.dataset_page_limit ??
  maximumResults
);

const datasetPageLimit = Math.max(
  1,
  Math.min(
    maximumResults,
    Number.isFinite(requestedDatasetPageLimit)
      ? Math.floor(requestedDatasetPageLimit)
      : maximumResults
  )
);

const maxTotalChargeUsd = Number(
  input.max_total_charge_usd ?? 0.50
);

if (
  !Number.isFinite(maxTotalChargeUsd) ||
  maxTotalChargeUsd <= 0 ||
  maxTotalChargeUsd > 5
) {
  throw new Error(
    'max_total_charge_usd must be greater than 0 and no more than 5 USD.'
  );
}

const sourcePolicyVersion = String(
  input.source_policy_version || '1.5.0'
).trim();

if (!sourcePolicyVersion) {
  throw new Error(
    'source_policy_version is required.'
  );
}

const queryPlanVersion =
  'google-maps-location-v2';

const actorBuildTag = String(
  input.apify_build_tag || 'latest'
);

const scopeKey = [
  sourceScopeKey,
  sourceId,
  segment,
  queryPlanVersion
].join('|');

const sourceJobId =
  input.source_job_id ||
  `${input.run_id}:${sourceId}:${locationKey}`;

const requestKey = [
  scopeKey,
  actorBuildTag,
  searchStrings.join(','),
  maxPerSearch
].join('|');

const warnings = [];

if (segment === 'horse_owner') {
  warnings.push(
    'Horse Owner discovery is limited to public horse-related businesses and facilities; ownership remains unverified.'
  );
}

return [{
  json: {
    ...input,

    contract_version:
      'a1.source-request.v2',

    run_id:
      String(input.run_id),

    source_job_id:
      sourceJobId,

    request_key:
      requestKey,

    scope_key:
      scopeKey,

    source_id:
      sourceId,

    platform_source_id:
      platformSourceId,

    source_name:
      'Google Maps via Apify',

    source_type:
      'google_maps',

    segment,

    location,
    location_key: locationKey,
    source_scope_key: sourceScopeKey,

    maximum_results:
      maximumResults,

    remaining_target:
      Math.max(
        0,
        Number(
          input.remaining_target ??
          maximumResults
        )
      ),

    previous_position:
      previousPosition,

    source_policy_id:
      'equinet-a1-approved-source-register',

    source_policy_version:
      sourcePolicyVersion,

    actor_id:
      actorId,

    actor_name:
      actorName,

    actor_build_tag:
      actorBuildTag,

    max_total_charge_usd:
      maxTotalChargeUsd,

    query_plan_version:
      queryPlanVersion,

    search_strings:
      searchStrings,

    planned_maximum_items:
      plannedMaximumItems,

    dataset_page_limit:
      datasetPageLimit,

    actor_started_this_execution:
      false,

    actor_input: {
      searchStringsArray:
        searchStrings,

      locationQuery,

      maxCrawledPlacesPerSearch:
        maxPerSearch,

      language:
        'en',

      countryCode:
        countryCode.toLowerCase(),

      scrapePlaceDetailPage:
        false,

      scrapeContacts:
        false,

      maxReviews:
        0,

      maxImages:
        0,

      includeWebResults:
        false,

      skipClosedPlaces:
        false
    },

    validation_warnings:
      warnings,

    force_new_actor_run:
      Boolean(input.force_new_actor_run),

    started_at:
      input.started_at ||
      new Date().toISOString()
  }
}];

const row = $json || {};
const request = row.request_payload || {};

const cursor =
  request.previous_position || {};

const cursorState =
  cursor.state || cursor;

const actorRunId =
  row.actor_run_id ||
  cursorState.actor_run_id ||
  null;

const datasetId =
  row.dataset_id ||
  cursorState.dataset_id ||
  null;

const currentStatus = String(
  row.actor_status ||
  cursorState.actor_status ||
  ''
).toUpperCase();

const forceNew =
  Boolean(request.force_new_actor_run);

const activeStatuses = new Set([
  'READY',
  'RUNNING',
  'TIMING-OUT',
  'ABORTING'
]);

const terminalFailureStatuses = new Set([
  'FAILED',
  'TIMED-OUT',
  'ABORTED',
  'START_FAILED'
]);

const activeOtherRuns = Math.max(
  0,
  Number(row.active_other_runs || 0)
);

const plannedMaximumItems = Math.max(
  1,
  Number(
    request.planned_maximum_items ||
    (
      Number(
        request.actor_input
          ?.maxCrawledPlacesPerSearch || 0
      ) *
      Number(
        request.actor_input
          ?.searchStringsArray?.length || 0
      )
    ) ||
    request.maximum_results ||
    1
  )
);

const datasetOffset = Math.max(
  0,
  Number(
    row.dataset_offset ??
    cursorState.dataset_offset ??
    0
  )
);

const storedDatasetExhausted =
  Boolean(
    row.dataset_exhausted ??
    cursorState.dataset_exhausted ??
    cursor.source_exhausted ??
    false
  );

const sameApplicationRunJob =
  Boolean(row.existing_job_found);

const priorDatasetCompleted =
  Boolean(actorRunId) &&
  Boolean(datasetId) &&
  currentStatus === 'SUCCEEDED' &&
  storedDatasetExhausted;

/*
 * A completed dataset from this same application run is terminal
 * for this run. A later application run starts a new bounded cycle.
 */
const completedInCurrentRun =
  sameApplicationRunJob &&
  priorDatasetCompleted;

const startFreshSearchCycle =
  !sameApplicationRunJob &&
  priorDatasetCompleted;

const sourceAlreadyExhausted =
 completedInCurrentRun;

const resumableExisting =
  Boolean(actorRunId) &&
  !priorDatasetCompleted &&
  (
    activeStatuses.has(currentStatus) ||
    (
      currentStatus === 'SUCCEEDED' &&
      Boolean(datasetId)
    )
  );

const currentActiveConflict =
  forceNew &&
  Boolean(actorRunId) &&
  activeStatuses.has(currentStatus);

let policyBlockError = null;

if (
  activeOtherRuns > 0 ||
  currentActiveConflict
) {
  policyBlockError = {
    code: 'SOURCE_CONCURRENCY_LIMIT',
    message:
      'Another Google Maps Apify Actor run is active. Source concurrency is limited to one.',
    retryable: true,
    stage: 'policy'
  };
} else if (
  actorRunId &&
  terminalFailureStatuses.has(currentStatus) &&
  !forceNew
) {
  policyBlockError = {
    code:
      'APIFY_TERMINAL_RUN_REQUIRES_FORCE_NEW',

    message:
      `Actor run ${actorRunId} ended with ` +
      `${currentStatus}. Set force_new_actor_run ` +
      `only after reviewing the failure.`,

    retryable: false,
    stage: 'policy'
  };
} else if (
  actorRunId &&
  !resumableExisting &&
  !sourceAlreadyExhausted &&
  !startFreshSearchCycle &&
  !forceNew
) {
  policyBlockError = {
    code: 'APIFY_RUN_STATE_UNSAFE_TO_RESTART',
    message:
      `Actor run ${actorRunId} has state ` +
      `${currentStatus || 'UNKNOWN'} and cannot ` +
      `be restarted automatically.`,
    retryable: false,
    stage: 'policy'
  };
}

const policyAllowsNewRun =
  !policyBlockError &&
  (
    !actorRunId ||
    forceNew ||
    startFreshSearchCycle
  );

const requestedPageLimit = Math.max(
  1,
  Number(
    request.dataset_page_limit ||
    request.maximum_results ||
    1
  )
);

const effectiveDatasetOffset =
  startFreshSearchCycle
    ? 0
    : datasetOffset;

const remainingDatasetBudget = Math.max(
  1,
  plannedMaximumItems - effectiveDatasetOffset
);

const datasetPageLimit = Math.max(
  1,
  Math.min(
    requestedPageLimit,
    remainingDatasetBudget
  )
);

return [{
  json: {
    ...request,

    existing_job_found:
      Boolean(row.existing_job_found),

    resume_existing:
      resumableExisting && !forceNew,

    source_already_exhausted:
      sourceAlreadyExhausted,

    actor_run_id:
  startFreshSearchCycle
    ? null
    : actorRunId,

dataset_id:
  startFreshSearchCycle
    ? null
    : datasetId,

actor_status:
  startFreshSearchCycle
    ? null
    : currentStatus || null,

dataset_offset: effectiveDatasetOffset,

dataset_exhausted:
  startFreshSearchCycle
    ? false
    : storedDatasetExhausted,

    job_status:
      row.job_status ||
      request.job_status ||
      null,

    actor_build_number:
      row.actor_build_number ||
      request.actor_build_number ||
      null,

    usage_total_usd:
      row.usage_total_usd == null
        ? null
        : Number(row.usage_total_usd),

    charged_event_counts:
      row.charged_event_counts || {},

    previous_job_error:
      row.last_error || null,

    active_other_runs:
      activeOtherRuns,

    planned_maximum_items:
      plannedMaximumItems,

    dataset_page_limit:
      datasetPageLimit,

    scope_key:
      request.scope_key ||
      row.scope_key,

    location_key:
      request.location_key ||
      row.location_key,

    actor_started_this_execution:
      false,

    policy_allows_new_run:
      policyAllowsNewRun,

    policy_block_error:
      policyBlockError,
    previous_actor_run_id:
  startFreshSearchCycle
    ? actorRunId
    : null,

previous_dataset_id:
  startFreshSearchCycle
    ? datasetId
    : null,

fresh_search_cycle:
  startFreshSearchCycle,
  }
}];

const row = $json || {};
const request =
  row.request_payload || row;

const actorRunId =
  row.actor_run_id ||
  request.actor_run_id;

if (!actorRunId) {
  throw new Error(
    'Cannot poll Apify without actor_run_id.'
  );
}

const datasetId =
  row.dataset_id ||
  request.dataset_id ||
  null;

const existingDeadline =
  request.poll_deadline_at
    ? Date.parse(request.poll_deadline_at)
    : NaN;

const pollDeadlineAt =
  Number.isFinite(existingDeadline)
    ? new Date(existingDeadline).toISOString()
    : new Date(
        Date.now() + 20 * 60 * 1000
      ).toISOString();

return [{
  json: {
    ...request,

    actor_run_id:
      actorRunId,

    dataset_id:
      datasetId,

    actor_status:
      String(
        row.actor_status ||
        request.actor_status ||
        'READY'
      ).toUpperCase(),

    job_status:
      row.job_status ||
      request.job_status ||
      'RUNNING',

    actor_build_number:
      row.actor_build_number ||
      request.actor_build_number ||
      null,

    dataset_offset:
      Math.max(
        0,
        Number(
          row.dataset_offset ??
          request.dataset_offset ??
          0
        )
      ),

    dataset_exhausted:
      Boolean(
        row.dataset_exhausted ??
        request.dataset_exhausted ??
        false
      ),

    scope_key:
      row.scope_key ||
      request.scope_key,

    location_key:
      row.location_key ||
      request.location_key,

    poll_deadline_at:
      pollDeadlineAt
  }
}];

const context =
  $('Prepare Poll State').item.json;

const run = $json || {};

const responseError = run.error
  ? String(
      run.error?.message ||
      run.error
    )
  : '';

const previousProviderStatus = String(
  context.actor_status || 'UNKNOWN'
).toUpperCase();

const providerStatus = responseError
  ? previousProviderStatus
  : String(
      run.status || 'UNKNOWN'
    ).toUpperCase();

const activeStatuses = new Set([
  'READY',
  'RUNNING',
  'TIMING-OUT',
  'ABORTING'
]);

const deadlineExceeded =
  Date.now() >=
  Date.parse(context.poll_deadline_at);

let actorError = null;

if (responseError) {
  actorError = {
    code:
      'APIFY_RUN_STATUS_FAILED',

    message:
      responseError,

    retryable:
      true,

    stage:
      'actor_poll'
  };
} else if (
  deadlineExceeded &&
  activeStatuses.has(providerStatus)
) {
  actorError = {
    code:
      'APIFY_POLL_DEADLINE_EXCEEDED',

    message:
      `Apify Actor run ` +
      `${context.actor_run_id} did not reach ` +
      `a terminal state before the deadline.`,

    retryable:
      true,

    stage:
      'actor_poll'
  };
} else if (
  !activeStatuses.has(providerStatus) &&
  providerStatus !== 'SUCCEEDED'
) {
  const errorCodes = {
    FAILED:
      'APIFY_ACTOR_FAILED',

    'TIMED-OUT':
      'APIFY_ACTOR_TIMED_OUT',

    ABORTED:
      'APIFY_ACTOR_ABORTED'
  };

  actorError = {
    code:
      errorCodes[providerStatus] ||
      'APIFY_ACTOR_UNEXPECTED_STATUS',

    message:
      String(
        run.statusMessage ||
        `Apify Actor ended with ` +
        `${providerStatus}.`
      ),

    retryable:
      providerStatus !== 'ABORTED',

    stage:
      'actor_run'
  };
}

return [{
  json: {
    ...context,

    actor_run_id:
      run.id ||
      context.actor_run_id,

    dataset_id:
      run.defaultDatasetId ||
      context.dataset_id ||
      null,

    actor_status:
      providerStatus,

    job_status:
      actorError
        ? 'FAILED'
        : providerStatus === 'SUCCEEDED'
          ? 'ACTOR_SUCCEEDED'
          : 'RUNNING',

    actor_build_number:
      run.buildNumber ||
      context.actor_build_number ||
      null,

    actor_run_data:
      run,

    usage_total_usd:
      run.usageTotalUsd == null
        ? context.usage_total_usd ?? null
        : Number(run.usageTotalUsd),

    charged_event_counts:
      run.chargedEventCounts ||
      context.charged_event_counts ||
      {},

    actor_error:
      actorError,

    continue_polling:
      activeStatuses.has(providerStatus) &&
      !deadlineExceeded &&
      !responseError
  }
}];

const context =
  $('Evaluate Actor Run').item.json;

const inputItems =
  $input.all().map(
    item => item.json || {}
  );

const datasetErrorItem =
  inputItems.find(item => item.error);

const datasetError =
  datasetErrorItem
    ? {
        code:
          'APIFY_DATASET_FETCH_FAILED',

        message:
          String(
            datasetErrorItem.error?.message ||
            datasetErrorItem.error
          ),

        retryable:
          true,

        stage:
          'dataset_fetch'
      }
    : null;

const rawItems = inputItems.filter(
  item =>
    !item.error &&
    Object.keys(item).length > 0
);

function text(value) {
  return value == null
    ? ''
    : String(value).trim();
}

function token(value) {
  return text(value)
    .toLowerCase()
    .normalize('NFKD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-|-$/g, '');
}

function domain(value) {
  const raw = text(value);

  if (!raw) {
    return '';
  }

  try {
    const parsed = new URL(
      raw.startsWith('http://') ||
      raw.startsWith('https://')
        ? raw
        : `https://${raw}`
    );

    return parsed.hostname
      .toLowerCase()
      .replace(/^www\./, '')
      .replace(/\.$/, '');
  } catch {
    return '';
  }
}

function phone(value) {
  return text(value)
    .replace(/\D/g, '');
}

function unique(values) {
  return [
    ...new Set(
      values
        .map(text)
        .filter(Boolean)
    )
  ];
}

const requestedCountry =
  text(
    context.location?.country_code
  ).toUpperCase();

const requestedRegionCode =
  token(
    context.location?.region_code ||
    context.location?.state_code
  );

const requestedRegionName =
  token(
    context.location?.region ||
    context.location?.state
  );

const allowedCities = new Set([
  context.location?.city,
  ...(
    Array.isArray(
      context.location?.city_aliases
    )
      ? context.location.city_aliases
      : []
  )
].map(token).filter(Boolean));

let closedRecords = 0;
let outOfAreaRecords = 0;
let invalidRecords = 0;
let duplicateRecords = 0;

const deduped = new Map();

const currentDatasetOffset = Math.max(
  0,
  Number(context.dataset_offset || 0)
);

for (
  let index = 0;
  index < rawItems.length;
  index++
) {
  const raw = rawItems[index];

  if (
    raw.permanentlyClosed === true ||
    raw.temporarilyClosed === true
  ) {
    closedRecords++;
    continue;
  }

  const title = text(raw.title);

  if (!title) {
    invalidRecords++;
    continue;
  }

  const rawCity =
    token(raw.city);

  const rawRegion =
    token(raw.state);

  const rawCountry =
    text(raw.countryCode)
      .toUpperCase();

  const cityAllowed =
    allowedCities.has(rawCity);

  const regionAllowed =
    !requestedRegionCode &&
    !requestedRegionName
      ? true
      : (
          rawRegion === requestedRegionCode ||
          rawRegion === requestedRegionName
        );

  const countryAllowed =
    rawCountry === requestedCountry;

  if (
    !cityAllowed ||
    !regionAllowed ||
    !countryAllowed
  ) {
    outOfAreaRecords++;
    continue;
  }

  const placeId =
    text(raw.placeId);

  const website =
    text(raw.website);

  const formattedPhone =
    text(
      raw.phone ||
      raw.phoneUnformatted
    );

  const fullAddress =
    text(raw.address);

  const sourceUrl =
    text(raw.url);

  const recordId =
    placeId ||
    text(raw.cid) ||
    text(raw.fid) ||
    `${token(title)}-${token(fullAddress)}`;

  if (!recordId) {
    invalidRecords++;
    continue;
  }

  let dedupKey;

  if (placeId) {
    dedupKey =
      `place:${placeId}`;
  } else if (domain(website)) {
    dedupKey =
      `domain:${domain(website)}`;
  } else if (phone(formattedPhone)) {
    dedupKey =
      `phone:${phone(formattedPhone)}`;
  } else {
    dedupKey =
      `name-address:` +
      `${token(title)}:` +
      `${token(fullAddress)}`;
  }

  const categories = unique([
    raw.categoryName,
    ...(
      Array.isArray(raw.categories)
        ? raw.categories
        : []
    )
  ]);

  const searchTerms = unique([
    raw.searchString
  ]);

  if (deduped.has(dedupKey)) {
    duplicateRecords++;

    const existing =
      deduped.get(dedupKey);

    existing.categories = unique([
      ...existing.categories,
      ...categories
    ]);

    existing.search_terms = unique([
      ...existing.search_terms,
      ...searchTerms
    ]);

    continue;
  }

  deduped.set(dedupKey, {
    source_id:
      context.source_id,

    platform_source_id:
      context.platform_source_id,

    source_record_id:
      recordId,

    google_place_id:
      placeId,

    source_url:
      sourceUrl,

    listing_url:
      sourceUrl,

    name:
      null,

    business_name:
      title,

    entity_type:
      'organisation',

    segment_hint:
      context.segment,

    horse_owner_proxy:
      context.segment === 'horse_owner',

    ownership_status:
      context.segment === 'horse_owner'
        ? 'unverified_business_proxy'
        : null,

    category:
      text(raw.categoryName),

    categories,
    search_terms: searchTerms,

    website,
    phone: formattedPhone,
    email: null,

    address:
      fullAddress,

    street:
      text(raw.street),

    city:
      text(raw.city),

    region:
      text(raw.state),

    region_code:
      context.location?.region_code ||
      context.location?.state_code ||
      null,

    state:
      text(raw.state),

    state_code:
      context.location?.region_code ||
      context.location?.state_code ||
      null,

    postal_code:
      text(raw.postalCode),

    country:
      requestedCountry,

    country_code:
      requestedCountry,

    coordinates:
      raw.location &&
      Number.isFinite(
        Number(raw.location.lat)
      ) &&
      Number.isFinite(
        Number(raw.location.lng)
      )
        ? {
            latitude:
              Number(raw.location.lat),

            longitude:
              Number(raw.location.lng)
          }
        : null,

    location_match:
      'exact_city',

    source_claims:
      categories,

    source_notes:
      context.segment === 'horse_owner'
        ? [
            'Public horse-related business or facility discovered through Google Maps; private horse ownership is not asserted.'
          ]
        : [
            'Public Farrier-related business discovered through Google Maps.'
          ],

    raw_reference: {
      provider:
        'apify',

      actor_id:
        context.actor_id,

      actor_name:
        context.actor_name,

      actor_run_id:
        context.actor_run_id,

      dataset_id:
        context.dataset_id,

      dataset_item_index:
        currentDatasetOffset + index,

      content_embedded:
        false
    },

    source_policy_version:
      context.source_policy_version,

    discovered_at:
      text(raw.scrapedAt) ||
      new Date().toISOString()
  });
}

const allNormalizedRecords = [
  ...deduped.values()
];

const parsedRecords =
  allNormalizedRecords.slice(
    0,
    Number(context.maximum_results)
  );

const pageLimit = Math.max(
  1,
  Number(
    context.dataset_page_limit ||
    context.maximum_results ||
    1
  )
);

const plannedMaximumItems = Math.max(
  1,
  Number(
    context.planned_maximum_items ||
    context.maximum_results ||
    1
  )
);

const nextDatasetOffset =
  datasetError
    ? currentDatasetOffset
    : currentDatasetOffset +
      rawItems.length;

const shortPage =
  rawItems.length < pageLimit;

const reachedPlannedMaximum =
  nextDatasetOffset >=
  plannedMaximumItems;

const datasetExhausted =
  !datasetError &&
  (
    shortPage ||
    reachedPlannedMaximum
  );

const sourceExhausted = false

const nextCursor =
  context.actor_run_id &&
  context.dataset_id
    ? {
        cursor_version:
          '1.2',

        source_id:
          context.source_id,

        segment:
          context.segment,

        location_key:
          context.location_key,

        scope_key:
          context.scope_key,

        mode:
          'apify_dataset',

        state: {
          actor_run_id:
            context.actor_run_id,

          dataset_id:
            context.dataset_id,

          actor_status:
            context.actor_status,

          dataset_offset:
            nextDatasetOffset,

          dataset_exhausted:
            datasetExhausted
        },

        source_exhausted:
          sourceExhausted,

        updated_at:
          new Date().toISOString()
      }
    : context.previous_position || {};

const warnings = [
  ...(context.validation_warnings || [])
];

if (context.segment === 'horse_owner') {
  warnings.push(
    'Google Maps results are public business/facility proxies; horse ownership remains unverified.'
  );
}

if (outOfAreaRecords) {
  warnings.push(
    `${outOfAreaRecords} out-of-area ` +
    `Google Maps result(s) were excluded.`
  );
}

if (closedRecords) {
  warnings.push(
    `${closedRecords} closed Google Maps ` +
    `result(s) were excluded.`
  );
}

const jobStatus =
  datasetError
    ? 'DATASET_FAILED'
    : datasetExhausted
      ? 'COMPLETED'
      : 'PARTIAL';

return [{
  json: {
    ...context,

    parsed_records:
      parsedRecords,

    parser_status:
      datasetError
        ? (
            parsedRecords.length
              ? 'partial'
              : 'failed'
          )
        : datasetExhausted
          ? 'completed'
          : 'partial',

    parser_error:
      datasetError,

    parser_warnings:
      warnings,

    source_exhausted:
      sourceExhausted,

    next_cursor:
      nextCursor,

    dataset_offset:
      nextDatasetOffset,

    dataset_exhausted:
      datasetExhausted,

    job_status:
      jobStatus,

    parser_summary: {
      queries_requested:
        Array.isArray(
          context.search_strings
        )
          ? context.search_strings.length
          : 0,

      actor_runs_started:
        context.actor_started_this_execution
          ? 1
          : 0,

      raw_records:
        rawItems.length,

      dataset_items_read:
        rawItems.length,

      dataset_offset_before:
        currentDatasetOffset,

      dataset_offset_after:
        nextDatasetOffset,

      normalized_records:
        parsedRecords.length,

      normalized_total_records:
        allNormalizedRecords.length,

      duplicate_records:
        duplicateRecords,

      closed_records:
        closedRecords,

      out_of_area_records:
        outOfAreaRecords,

      invalid_records:
        invalidRecords
    },

    finished_at:
      new Date().toISOString()
  }
}];
